<body>
<a class="skip-link" href="#main">Skip to game</a><div class="app t00"><header class="topbar panel"><div class="brand"><h1>Orchard Catch Arcade</h1><p class="tagline">High-score challenge mode.</p></div><dl class="stats" aria-label="Game statistics"><div class="stat"><dt>Basket</dt><dd data-s02="caught">0 / 0</dd></div><div class="stat"><dt>Goal</dt><dd data-s02="goal">0</dd></div></dl></header><main class="play" id="main"><div class="stage" data-s02="stage" tabindex="0" role="application" aria-label="Fruit-catching stage; move the basket with the mouse, arrow keys or a tap"><div class="fruit-layer" data-s02="fruits"></div><div class="basket" data-s02="basket" aria-hidden="true"></div></div></main><footer class="dock panel"><p class="message" data-s02="message" aria-live="polite">Move the basket to catch the fruit.</p><!-- s02:hook:html -->
<section class="hook-zone" aria-label="Points, streak and pacing feedback">
  <div class="hook-grid">
    <div class="hook-card"><span class="hook-label">Score</span><strong class="hook-value" data-s02="points">0</strong></div>
    <div class="hook-card"><span class="hook-label">Combo</span><strong class="hook-value" data-s02="streak">0</strong>x</div>
    <div class="hook-card"><span class="hook-label">Level</span><strong class="hook-value" data-s02="pace">1</strong><span class="hook-sub" data-s02="round">Round 1</span></div>
  </div>
</section>
<!-- /s02:hook:html --><button type="button" class="btn btn--solid" data-s02="restart">Restart</button></footer><div class="overlay" data-s02="overlay" hidden><div class="overlay-panel"><h2>Basket Full!</h2><p data-s02="detail">Lovely picking.</p><button type="button" class="btn btn--solid" data-s02="playagain">Next Round</button></div></div></div>
<script>

(function () {
  'use strict';
  // Arcade Config: Base difficulty increases per round
  var CFG = {"goal": 10, "input": "pointer", "pitch": 900, "seed": 2201, "speed": 1.0};

  function all(role) { return Array.prototype.slice.call(document.querySelectorAll('[data-s02="' + role + '"]')); }
  function one(role) { return document.querySelector('[data-s02="' + role + '"]'); }
  function set(role, text) { all(role).forEach(function (node) { node.textContent = String(text); }); }

  var S02 = window.S02 = window.S02 || { onCatch: [], onMiss: [], onWin: [], onRestart: [] };
  function emit(name, data) { (S02[name] || []).forEach(function (fn) { try { fn(data); } catch (err) {} }); }

  // Audio Synthesis
  var audioCtx = null;
  function playTone(freq, type, duration) {
    if (!audioCtx) return;
    var osc = audioCtx.createOscillator();
    var gain = audioCtx.createGain();
    osc.type = type;
    osc.frequency.value = freq;
    gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + duration);
  }

  function log(text) {
    var list = one('log'); if (!list) { return; }
    var li = document.createElement('li'); li.textContent = text; list.insertBefore(li, list.firstChild);
    while (list.children.length > 5) { list.removeChild(list.lastChild); }
  }

  var seed = CFG.seed >>> 0;
  function rand() { seed = (seed * 1664525 + 1013904223) >>> 0; return seed; }

  var caught = 0, missed = 0, goal = CFG.goal, fruits = [], spawnAt = 0, last = 0, won = false;
  var basketX = 0;

  // Arcade State
  var round = 1;
  var combo = 0;
  var score = 0;
  var highScore = parseInt(localStorage.getItem('orchard_highscore') || '0', 10);

  function stageSize() { var stage = one('stage'); return { w: stage.clientWidth || 640, h: stage.clientHeight || 380 }; }

  function paint() {
    set('caught', caught + ' / ' + goal); 
    set('goal', String(goal)); 
    // Note: 'missed' role not in HTML template, but logic kept for internal consistency if needed elsewhere
    var meter = one('meter'); if (meter) { meter.style.width = Math.round(100 * caught / goal) + '%'; }
    var status = one('status'); if (status) { status.textContent = caught >= goal ? 'Full' : 'Picking'; }
  }

  function moveBasket(x) {
    var basket = one('basket'); if (!basket) { return; }
    var size = stageSize(); basketX = Math.max(60, Math.min(size.w - 60, x));
    basket.style.left = basketX + 'px';
  }

  function spawn() {
    var size = stageSize();
    var fruit = document.createElement('div');
    var kind = rand() % 4;
    fruit.className = 'fruit fruit-' + kind;
    // Arcade: Wider spread
    var x = 30 + (rand() % Math.max(60, size.w - 60));
    // Arcade: Speed scales with round
    var speedMod = 1 + (round * 0.15); 
    var speed = (1.2 + (rand() % 60) / 100) * CFG.speed * speedMod;

    fruit.style.left = x + 'px'; fruit.style.top = '-40px';
    one('fruits').appendChild(fruit);
    fruits.push({ node: fruit, x: x, y: -40, speed: speed, radius: 17 });
  }

  function removeFruit(index) {
    var item = fruits[index];
    if (item && item.node && item.node.parentNode) { item.node.parentNode.removeChild(item.node); }
    fruits.splice(index, 1);
  }

  function createParticles(x, y, color) {
    var container = one('fruits');
    for (var i=0; i<6; i++) {
      var p = document.createElement('div');
      p.className = 'particle';
      p.style.left = x + 'px';
      p.style.top = y + 'px';
      p.style.backgroundColor = color;
      // Random direction
      var angle = Math.random() * Math.PI * 2;
      var dist = 30 + Math.random() * 40;
      p.style.setProperty('--tx', Math.cos(angle)*dist + 'px');
      p.style.setProperty('--ty', Math.sin(angle)*dist + 'px');
      container.appendChild(p);
      setTimeout(function(){ if(p.parentNode) p.parentNode.removeChild(p); }, 400);
    }
  }

  function miss(index) {
    removeFruit(index); 
    missed += 1; 
    combo = 0; // Reset combo on miss
    paint();

    // Visual Shake
    var stage = one('stage');
    if(stage) {
        stage.classList.remove('shake');
        void stage.offsetWidth; // trigger reflow
        stage.classList.add('shake');
    }

    log('Missed a fruit. Combo reset.');
    set('message', 'Oops! Lost your streak.');
    playTone(150, 'sawtooth', 0.3); // Sad sound
    emit('onMiss', { missed: missed, caught: caught });
  }

  function catchFruit(index) {
    var item = fruits[index];
    removeFruit(index); 
    caught += 1; 

    // Combo Logic
    combo += 1;
    var pointsEarned = 10 * (1 + Math.floor(combo / 5)); // Bonus every 5 hits
    score += pointsEarned;

    paint();

    // Visuals
    createParticles(item.x, item.y + item.radius, getComputedStyle(one('fruits')).color); // Use a generic color or specific
    playTone(440 + (combo * 10), 'sine', 0.15); // Pitch goes up with combo

    log('Caught! +' + pointsEarned + ' pts.');
    set('message', 'Nice catch! Score: ' + score);
    emit('onCatch', { caught: caught, goal: goal });

    if (caught >= goal) { win(); }
  }

  function win() {
    won = true;
    var overlay = one('overlay');
    if (overlay) { overlay.hidden = false; set('detail', 'Round cleared! Next round is faster.'); }
    set('message', 'Basket full. Get ready for speed up!');
    playTone(600, 'square', 0.4); // Win sound

    // High Score Logic
    if (score > highScore) {
        highScore = score;
        try { localStorage.setItem('orchard_highscore', String(highScore)); } catch(e){}
        set('detail', 'New High Score: ' + highScore + '!');
    }

    emit('onWin', { caught: caught, missed: missed });
  }

  function step(timestamp) {
    var size = stageSize();
    if (!last) { last = timestamp; }
    var elapsed = Math.min(60, timestamp - last); last = timestamp;

    // Arcade Difficulty: Spawn rate increases with round
    var currentPitch = CFG.pitch / (1 + (round * 0.2));

    if (!won && timestamp >= spawnAt) { spawn(); spawnAt = timestamp + currentPitch; }

    var i;
    for (i = fruits.length - 1; i >= 0; i -= 1) {
      var item = fruits[i];
      item.y += item.speed * (elapsed / 16.67);
      item.node.style.top = item.y + 'px';

      if (item.y > size.h + 30) { miss(i); continue; }

      // Hit detection
      var inBasketBand = item.y + item.radius * 2 >= size.h - 62 && item.y <= size.h - 24;
      if (inBasketBand && Math.abs((item.x + item.radius) - basketX) < 52) { catchFruit(i); }
    }
    window.requestAnimationFrame(step);
  }

  function restart() {
    while (fruits.length) { removeFruit(0); }
    caught = 0; missed = 0; won = false; last = 0; spawnAt = 0;
    combo = 0;
    score = 0; // Arcade mode: score persists until full restart? Let's reset on button but keep highscore.

    var size = stageSize(); moveBasket(size.w / 2);
    paint(); 
    set('message', 'Round ' + round + ' - Catch the fruit!');
    var overlay = one('overlay'); if (overlay) { overlay.hidden = true; }

    // Initialize Audio Context on first user interaction if needed, but here we just try to play
    if (!audioCtx) {
        try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e){}
    }

    emit('onRestart', {});
  }

  // New Round Logic
  function nextRound() {
    round += 1;
    restart();
  }

  var stage = one('stage');
  if (stage) {
    stage.addEventListener('pointermove', function (event) {
      if (CFG.input === 'keys' || CFG.input === 'tap') { return; }
      var rect = stage.getBoundingClientRect(); moveBasket(event.clientX - rect.left);
    });
    stage.addEventListener('pointerdown', function (event) {
      if (CFG.input === 'keys') { return; }
      var rect = stage.getBoundingClientRect(); moveBasket(event.clientX - rect.left);
    });
    stage.addEventListener('keydown', function (event) {
      if (CFG.input === 'pointer' || CFG.input === 'tap') { return; }
      if (event.key === 'ArrowLeft') { event.preventDefault(); moveBasket(basketX - 32); }
      if (event.key === 'ArrowRight') { event.preventDefault(); moveBasket(basketX + 32); }
    });
  }

  all('restart').forEach(function (button) { button.addEventListener('click', function() { round=1; score=0; restart(); }); });
  all('playagain').forEach(function (button) { button.addEventListener('click', nextRound); });

  var initial = stageSize(); basketX = initial.w / 2; moveBasket(basketX); paint();
  window.requestAnimationFrame(step);
})();


/* Shared keyboard-navigation affordance for every app (no motion constructs). */
(function () {
  'use strict';
  document.addEventListener('keydown', function (event) {
    if (event.key !== 'Home' && event.key !== 'End') { return; }
    var body = document.body;
    if (!body) { return; }
    window.scrollTo(0, event.key === 'Home' ? 0 : body.scrollHeight);
  });
})();


/* Orchard Catch keyboard help and focus affordance. */
(function () {
  'use strict';
  var stage = document.querySelector('[data-s02="stage"]');
  if (!stage) { return; }
  stage.addEventListener('focus', function () { stage.setAttribute('data-focused', 'true'); });
  stage.addEventListener('blur', function () { stage.removeAttribute('data-focused'); });
  document.addEventListener('keydown', function (event) {
    if (event.key !== '?') { return; }
    var message = document.querySelector('[data-s02="message"]');
    if (message) { message.textContent = 'Use Mouse or Arrow Keys to move. Catch fruit for combos!'; }
  });
})();

/* s02:hook:js */
(function () {
  'use strict';
  var points = 0, streak = 0, ticks = 0, round = 1;

  function set(role, text) {
    var nodes = document.querySelectorAll('[data-s02="' + role + '"]');
    for (var i = 0; i < nodes.length; i += 1) { nodes[i].textContent = String(text); }
  }

